export const getGetHistoryUrl = (id: number,
    params?: GetHistoryParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/clients/${id}/operations?${stringifiedParams}` : `/api/clients/${id}/operations`
}

export const getHistory = async (id: number,
    params?: GetHistoryParams, options?: Parameters<typeof customFetch>[1]): Promise<History> => {

  return customFetch<History>(getGetHistoryUrl(id,params),
  {
    ...options,
    method: 'GET'


  }
);}





